#include <stdio.h>

int add(int a, int b) {
    return a + b;
}

int sub(int a, int b) {
    return a - b;
}

int mul(int a, int b) {
    return a * b;
}

int divide(int a, int b) {
    return a / b;
}

void showMenu(void) {
    printf("=== 小鱼干计算器 ===\n");
    printf("1. 加法\n");
    printf("2. 减法\n");
    printf("3. 乘法\n");
    printf("4. 除法\n");
    printf("5. 收工\n");
    printf("选一个（1-5）：");
}

int main(void) {
    int choice = 0;
    int a = 0;
    int b = 0;

    showMenu();
    if (scanf("%d", &choice) != 1) {
        printf("\n下次再来喵～\n");
        return 0;
    }

    if (choice == 5) {
        printf("收工啦喵～\n");
        return 0;
    }

    printf("第一条小鱼干：");
    if (scanf("%d", &a) != 1) {
        printf("\n下次再来喵～\n");
        return 0;
    }
    printf("第二条小鱼干：");
    if (scanf("%d", &b) != 1) {
        printf("\n下次再来喵～\n");
        return 0;
    }

    if (choice == 1) {
        printf("%d + %d = %d\n", a, b, add(a, b));
    } else if (choice == 2) {
        printf("%d - %d = %d\n", a, b, sub(a, b));
    } else if (choice == 3) {
        printf("%d * %d = %d\n", a, b, mul(a, b));
    } else {
        printf("%d / %d = %d\n", a, b, divide(a, b));
    }
    return 0;
}
